/bin/bash -lc "python - <<'PY'
import numpy as np
from solve import Controller
ROTS={
 'xpinch': np.array([[0.,1.,0.],[1.,0.,0.],[0.,0.,-1.]]),
 'xpinch_flip': np.array([[0.,-1.,0.],[-1.,0.,0.],[0.,0.,-1.]])
}

def attempt(rot, xoff, z, pull):
 c=Controller(); c.data.ctrl[:7]=c.data.qpos[:7]; c.data.ctrl[7]=140; c.hold(40)
 drawer=c.data.xpos[c.drawer_body_id].copy(); handle=drawer+np.array([0.093,0,0])
 seq=[(handle+np.array([xoff,0,0.14]),140,20),(handle+np.array([xoff,0,0.06]),140,20),(handle+np.array([xoff,0,z]),80,20),(handle+np.array([xoff,0,z]),0,25),(handle+np.array([xoff+pull,0,z]),0,40)]
 mo=0
 for pos,g,ch in seq:
  c.move_pinch(pos,g,rot=rot,chunks=ch,sim_steps=8)
  mo=max(mo,c.drawer_open())
 c.hold(80,grip=0)
 mo=max(mo,c.drawer_open())
 return mo,c.drawer_open(),c.block_pos()[2]
for rname,rot in ROTS.items():
 for xoff in [-0.01,0.0,0.01,0.02]:
  for z in [0.025,0.015,0.005,-0.005]:
   for pull in [0.1,0.14,0.18]:
    mo,fo,bz=attempt(rot,xoff,z,pull)
    print(rname,'xoff',xoff,'z',z,'pull',pull,'max',round(mo,4),'final',round(fo,4),'bz',round(float(bz),4))
PY"
